// KAIST Daejeon main campus (한국과학기술원 대전 본원, 대전 유성구). Data is generated by scripts/campuses/kaist/build-package.mjs
// from the pilot (pilot/kaist-daejeon): 103 destructible buildings (본관·학술문화관·창의학습관·KI빌딩 detailed, 정문 custom,
// 98 generic), no protected building (user decision 2026-10-20: 학생회관-1 (church inside), 태울관 health room and the E21
// 파팔라도 메디컬센터 clinic are destructible), a baked ground with the pilot's ground shader (the SKKU port
// src/campuses/skku/ground-look.js; the pilot's final-materials.js is the same shader as dankook's), the 오리연못 (water shader of
// pilot/kaist-daejeon/landscape/landscape.mjs, ported below to world units) and the non-destructible context (대덕연구단지·어은동·궁동)
// fading into the haze. Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, KA_PLACEMENTS, KA_BUILDING_BASE, KA_HEIGHT_GRIDS, KA_HEIGHT_RANGE_M, KA_ENV_IDS, KA_ENV_MANIFEST_IDS, KA_LOOK, KA_ZONES, KA_DISPLAY, KA_PROVENANCE } from './data.js';
import { KA_FOOTPRINTS } from './footprints.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';
import { batchBuildingMaterials } from './batch-materials.js';

const MODEL_IDS = Object.freeze(KA_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/kaist/${file}`, import.meta.url).href;
const HAZE = KA_DISPLAY.haze || '#dde5e8', FADE = KA_DISPLAY.fade;

// 오리연못 water: landscape/landscape.mjs onBeforeCompile (ripples, two fountain rings, depth colour, sky / tree reflection, sun glint).
// The pilot works in metres; the game scene is metres x worldUnitsPerMeter, so world positions are scaled back to metres first.
function createPondWater(THREE, W) {
  const unit = (1 / W).toFixed(6);
  return material => {
    if (!material.userData?.kaistWater) return false;
    material.metalness = 0; material.roughness = .14;
    material.onBeforeCompile = sh => {
      sh.vertexShader = sh.vertexShader
        .replace('#include <common>', '#include <common>\nvarying vec3 vWp;\nvarying vec2 vPondUv;')
        .replace('#include <uv_vertex>', '#include <uv_vertex>\n#ifdef USE_UV\nvPondUv = uv;\n#else\nvPondUv = vec2(0.5, 0.5);\n#endif')
        .replace('#include <worldpos_vertex>', `#include <worldpos_vertex>\nvWp = (modelMatrix * vec4(transformed, 1.0)).xyz * ${unit};`);
      sh.fragmentShader = sh.fragmentShader
        .replace('#include <common>', '#include <common>\nvarying vec3 vWp;\nvarying vec2 vPondUv;')
        .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
{
  vec2 q = vWp.xz;
  float dF1 = length(q - vec2(44.0, 64.0));
  float dF2 = length(q - vec2(28.0, 108.0));
  float rWave = sin(dF1 * 2.4) * exp(-dF1 * 0.045) + sin(dF2 * 2.6) * exp(-dF2 * 0.05);
  vec3 rp = vec3(
    sin(q.x * 1.15 + q.y * 0.45) * 0.55 + sin(q.x * 0.31 - q.y * 1.45) * 0.40 + cos(q.x * 2.3 + q.y * 1.8) * 0.25 + rWave * 0.9,
    0.0,
    cos(q.y * 1.05 - q.x * 0.38) * 0.55 + cos(q.x * 1.85 + q.y * 0.28) * 0.35 + sin(q.y * 2.5 - q.x * 1.6) * 0.25 + rWave * 0.9
  ) * 0.055;
  normal = normalize(normal + (viewMatrix * vec4(rp, 0.0)).xyz);
}`)
        .replace('#include <color_fragment>', `#include <color_fragment>
{
  vec2 q = vWp.xz;
  float shoreT = clamp(vPondUv.x, 0.0, 1.0);
  float dCenter = clamp(length(q - vec2(24.0, 78.0)) / 92.0, 0.0, 1.0);
  float depthT = clamp(shoreT * 0.72 + (1.0 - dCenter) * 0.28, 0.0, 1.0);
  vec3 shallowCol = vec3(0.18, 0.39, 0.36);
  vec3 midCol     = vec3(0.08, 0.25, 0.33);
  vec3 deepCol    = vec3(0.04, 0.16, 0.24);
  vec3 baseWater  = mix(shallowCol, mix(midCol, deepCol, smoothstep(0.30, 1.0, depthT)), smoothstep(0.0, 0.55, depthT));
  float waveCaus  = 0.5 + 0.5 * sin(q.x * 1.35 + sin(q.y * 0.85) * 1.5) * cos(q.y * 1.25 - cos(q.x * 0.75) * 1.4);
  float shoreFoam = smoothstep(0.14, 0.0, shoreT) * (0.55 + 0.45 * sin(q.x * 3.2 + q.y * 2.9));
  float dF1 = length(q - vec2(44.0, 64.0));
  float dF2 = length(q - vec2(28.0, 108.0));
  float fRing = (smoothstep(0.65, 1.0, sin(dF1 * 2.1)) * exp(-dF1 * 0.06) + smoothstep(0.65, 1.0, sin(dF2 * 2.3)) * exp(-dF2 * 0.065)) * 0.26;
  vec3 V = normalize(cameraPosition * ${unit} - vWp);
  float NdotV = clamp(abs(V.y), 0.0, 1.0);
  float fresnel = pow(1.0 - NdotV, 3.0);
  float treeReflMask = smoothstep(22.0, 4.0, length(q - vec2(-4.0, 70.0))) * 0.65 + (1.0 - shoreT) * 0.45;
  vec3 skyRefl = mix(vec3(0.32, 0.50, 0.62), vec3(0.14, 0.29, 0.22), clamp(treeReflMask, 0.0, 0.80));
  vec3 sunDir = normalize(vec3(0.52, 0.74, 0.42));
  vec3 H = normalize(V + sunDir);
  float waveN = sin(q.x * 1.7 + q.y * 1.1) * cos(q.y * 1.9 - q.x * 1.3);
  float spec = pow(clamp(H.y + waveN * 0.045, 0.0, 1.0), 56.0) * 0.28;
  diffuseColor.rgb = mix(baseWater + vec3(0.04, 0.08, 0.08) * waveCaus * (1.0 - depthT * 0.45), skyRefl, clamp(fresnel * 0.42 + 0.08, 0.0, 0.48));
  diffuseColor.rgb += vec3(0.35, 0.46, 0.50) * (shoreFoam * 0.30 + fRing) + vec3(0.75, 0.84, 0.90) * spec;
}`);
    };
    material.customProgramCacheKey = () => 'kaist-pond1';
    material.needsUpdate = true;
    return true;
  };
}
const groundLook = createSkkuGroundLook(KA_LOOK, KA_ZONES);
const materialHook = (THREE, ctx) => { const ground = groundLook(THREE, ctx), water = createPondWater(THREE, ctx.worldUnitsPerMeter ?? WORLD_UNITS_PER_METER);
  return material => water(material) || ground(material); };

export const KAIST = Object.freeze({
  id: 'kaist',
  meta: Object.freeze({ school: '한국과학기술원(KAIST)', campus: '대전 본원', short: 'KAIST', modelNoun: 'KAIST' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: KA_PLACEMENTS,
  approvedCount: KA_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['mainBldg', 'library', 'creativeLearning', 'kiBldg', 'mainGate']),
  startBuildingId: 'kiBldg',
  // Start: from the south-east (정문 side), up the 진입 축 over the 오리연못 (fountains, island, bridge) with KI빌딩 on the right
  // and 학술문화관 beyond. World units (metres x 0.5, z = -N); azimuth .62 = camera to the south-east of the box.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-30, -1, -55]), max: Object.freeze([78, 14, 30]), azimuth: .62 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: KA_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: batchBuildingMaterials,
  }),
  terrain: Object.freeze({ heightGrids: KA_HEIGHT_GRIDS, buildingBase: KA_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, canopy lowered by an estimate, 오리연못 water datum 0 + floor / photo level evidence, pilot/kaist-daejeon); not a survey' }),
  environment: Object.freeze({ provenance: KA_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the pond estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: KA_ENV_IDS, castShadow: Object.freeze([]), materialHook,
      fade: Object.freeze({ centre_m: Object.freeze(FADE ? [...FADE.centreEN] : [-90, 329]), near_m: FADE?.r0_m ?? 560, far_m: FADE?.r1_m ?? 1300, ...(FADE?.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/kaist-daejeon preview ground + 오리연못 + context, baked' }),
  }),
  // No protected building (src/campuses/kaist/protected.js is empty): no pkg.protected, so src/protected-buildings.js is never used.
  // Hazard tape around every building (src/engine/hazard-tape.js): none on the context.
  hazardTape: Object.freeze({ footprints: KA_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 760, far: 2400 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-170, 150, 60]), shadowSpan: 260 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: KA_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default KAIST;
